import type { ProfileCategory, ProfileModel } from './profile-systems';

export const RAILINGS_HUB = '/sklyani-ohorozhi/';
export const RAILINGS_IMG = '/images/catalog/sklyani-ohorozhi';
const P = (slug: string) => `${RAILINGS_HUB}${slug}/`;

const m = (id: string, name: string, kind: string, blurb: string, specs: [string, string][], features: string[], imageAlt: string, image = id): ProfileModel =>
  ({ id, name, kind, image, imageAlt, blurb, specs, features });

