const COMPARE = ['Варіант', 'Кріплення', 'Скло', 'Особливість', 'Для чого'];

interface RailingPage extends Omit<ProfileCategory, 'group' | 'path' | 'eyebrow' | 'heroImage' | 'imageBase' | 'process' | 'compareColumns' | 'faq'> {
  path?: string;
  eyebrow: string;
  faq: [string, string][];
}

const page = (p: RailingPage): ProfileCategory => {
  if (p.models.length !== 6 || p.faq.length !== 8) throw new Error(`railing page ${p.slug}: expected 6 models and 8 own FAQs`);
  return {
    ...p,
    group: 'railings',
    path: p.path ?? P(p.slug),
    eyebrow: `Скляні огорожі / ${p.eyebrow}`,
    heroImage: `hero-${p.slug}`,
    imageBase: RAILINGS_IMG,
    process: PROCESS,
    compareColumns: COMPARE,
    faq: [...p.faq, ...COMMON],
    catalogButton: 'Переглянути варіанти',
    optionsLabel: 'Варіант',
    catalogNote: 'Параметри наведені для типових конфігурацій. Товщину скла, крок кріплень і висоту визначаємо після заміру з урахуванням основи та навантаження.'
  };
};

